// Define category pairs
let E_pairs = [["E1","E2"], ["E3","E4"], ["E5","E6"]];
let M_pairs = [["M1","M2"], ["M3","M4"], ["M5","M6"]];
let H_pairs = [["H1","H2"], ["H3","H4"], ["H5","H6"]];

// Function to randomly pick one pair
function pickRandomPair(pairs) {
    let randomIndex = Math.floor(Math.random() * pairs.length);
    return pairs[randomIndex];
}

// Randomly select one pair from each group
let selectedE = pickRandomPair(E_pairs);
let selectedM = pickRandomPair(M_pairs);
let selectedH = pickRandomPair(H_pairs);

// Combine all selected elements
let allSelected = [...selectedE, ...selectedM, ...selectedH];

// Create final message format
msg.payload = {
    language: global.get('lang'),
    chapters: allSelected
};

return msg;

// Load saved state
let index = context.get("index") || 0;
let chapters = context.get("chapters");

// If a new chapters list arrives, store it and reset index
if (msg.payload && msg.payload.chapters) {
    chapters = msg.payload.chapters;
    context.set("chapters", chapters);
    index = 0;
    context.set("index", index);
}

// Stop if no chapters available
if (!chapters || chapters.length === 0) {
    return null;
}

// Stop if all chapters have been sent
if (index >= chapters.length) {
    context.set("chapters", null);
    context.set("index", 0);
    msg.payload = "complete"
    return msg;
}

// Get current chapter
let currentChapter = chapters[index];

// Output only the current chapter
global.set('question',currentChapter)
msg.payload = currentChapter;

// Increment index for next run
index += 1;
context.set("index", index);

return msg;

