// Detect string values from "s1" to "sTARGET_COUNT"
// Example: s1, s2, s3 ... s20
// Order does NOT matter
// When all received, send "complete" and set global.testresult = "yes"
// Reset with msg.reset = true or msg.payload = "reset"
// On reset, set global.testresult = "no" and clear received numbers

const TARGET_COUNT = 6;
const PREFIX = "s";

let received = context.get("received") || {};

// RESET
if (msg.reset === true || msg.payload === "reset") {
    context.set("received", {});
    global.set("testresult", "no");

    node.status({
        fill: "red",
        shape: "dot",
        text: "reset / testresult = no"
    });

    return null;
}

// Convert payload to string
let value = String(msg.payload).trim().toLowerCase();

// Accept s1, s20, or s20,0
let regex = new RegExp("^" + PREFIX + "(\\d+)");
let match = value.match(regex);

if (!match) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "ignored: " + value
    });
    return null;
}

let num = Number(match[1]);

if (!Number.isInteger(num) || num < 1 || num > TARGET_COUNT) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "ignored: " + value
    });
    return null;
}

// Save received number
received[num] = true;
context.set("received", received);

// Find missing numbers
let missing = [];

for (let i = 1; i <= TARGET_COUNT; i++) {
    if (!received[i]) {
        missing.push(i);
    }
}

let count = TARGET_COUNT - missing.length;

node.status({
    fill: "yellow",
    shape: "dot",
    text: count + "/" + TARGET_COUNT + " received, missing: " + missing.join(",")
});

